            // 保存折叠状态到localStorage
            const isCollapsed = content.classList.contains('collapsed');
            localStorage.setItem(`${characterId}-collapsed`, isCollapsed);
        }

        // 恢复折叠状态
        function restoreCollapseStates() {
            const characters = ['alicia', 'coco', 'user'];
            characters.forEach(charId => {
                const isCollapsed = localStorage.getItem(`${charId}-collapsed`) === 'true';
                if (isCollapsed) {
                    document.getElementById(`${charId}-content`).classList.add('collapsed');
                    document.getElementById(`${charId}-arrow`).classList.add('collapsed');
                }
            });
        }

        // MVU数据获取函数 - 根据环境自动选择
        async function getMVUData() {
            try {
                // 方法1: 尝试从全局变量获取（如果在EJS环境中预先设置）
                if (typeof window.statData !== 'undefined') {
                    return window.statData;
                }

                // 方法2: 尝试使用getvar（EJS环境）
                if (typeof getvar === 'function') {
                    return await getvar('stat_data');
                }

                // 方法3: 尝试使用getVariables（酒馆助手环境）
                if (typeof getVariables === 'function') {
                    const vars = getVariables();
                    return vars.stat_data;
                }

                // 方法4: 尝试从父窗口获取（如果在iframe中）
                if (window.parent && window.parent !== window) {
                    if (typeof window.parent.getvar === 'function') {
                        return await window.parent.getvar('stat_data');
                    }
                    if (typeof window.parent.getVariables === 'function') {
                        const vars = window.parent.getVariables();
                        return vars.stat_data;
                    }
                }

                // 方法5: 尝试通过消息通信获取
                if (window.parent && window.parent !== window) {
                    return new Promise((resolve, reject) => {
                        const messageHandler = (event) => {
                            if (event.data && event.data.type === 'stat_data') {
                                window.removeEventListener('message', messageHandler);
                                resolve(event.data.data);
                            }
                        };
                        window.addEventListener('message', messageHandler);
                        window.parent.postMessage({ type: 'request_stat_data' }, '*');

                        // 超时处理
                        setTimeout(() => {
                            window.removeEventListener('message', messageHandler);
                            reject(new Error('获取数据超时'));
                        }, 5000);
                    });
                }

                throw new Error('无法获取MVU数据');

            } catch (error) {
                console.error('获取MVU数据失败:', error);
                return null;
            }
        }

        async function loadStatusData() {
            const data = await getMVUData();

            if (!data) {
                document.querySelector('.status-container').innerHTML =
                    '<div class="error-message">⚠️ 无法获取状态数据<br>请确保MVU系统正常运行</div>';
                return;
            }

            // 更新世界信息
            if (data["世界"]) {
                document.getElementById('world-time').textContent =
                    data["世界"]["当前时间"] ? data["世界"]["当前时间"][0] : "未知";
                document.getElementById('world-location').textContent =
                    data["世界"]["当前地点"] ? data["世界"]["当前地点"][0] : "未知";
                document.getElementById('world-days').textContent =
                    data["世界"]["旅行天数"] ? data["世界"]["旅行天数"][0] : "0";
            }

            // 更新爱莉希雅信息
            if (data["爱莉希雅"]) {
                updateCharacterData('alicia', data["爱莉希雅"]);
            }

            // 更新可可信息
            if (data["可可"]) {
                updateCharacterData('coco', data["可可"]);
            }

            // 更新用户信息
            if (data["user"]) {
                updateUserData(data["user"]);
            }
        }

        function updateCharacterData(charId, charData) {
            // 基础属性
            if (charData["基础属性"]) {
                const basicAttrs = charData["基础属性"];
                if (basicAttrs["冒险等级"]) {
                    document.getElementById(`${charId}-level`).textContent = basicAttrs["冒险等级"][0];
                }
                if (basicAttrs["冒险功绩点"] !== undefined) {
                    document.getElementById(`${charId}-points`).textContent = basicAttrs["冒险功绩点"][0] + " 点";
                }
                if (basicAttrs["职业等级"]) {
                    document.getElementById(`${charId}-class`).textContent = basicAttrs["职业等级"][0];
                }
            }

            // 外观描述
            if (charData["外观描述"]) {
                const appearanceDiv = document.getElementById(`${charId}-appearance`);
                appearanceDiv.innerHTML = '';
                const appearanceEmojis = {
                    "头饰": "👑",
                    "上身": "👔",
                    "下身": "👖",
                    "袜子": "🧦",
                    "内裤": "🩲",
                    "内衣": "👙"
                };

                for (let [key, value] of Object.entries(charData["外观描述"])) {
                    if (value && value[0]) {
                        const emoji = appearanceEmojis[key] || "✨";
                        appearanceDiv.innerHTML += `<div class="description-item">${emoji} ${key}: ${value[0]}</div>`;
                    }
                }
            }

            // 身体状态
            if (charData["身体状态"]) {
                const bodyDiv = document.getElementById(`${charId}-body`);
                bodyDiv.innerHTML = '';
                const bodyEmojis = {
                    "表情": "😊",
                    "动作": "🏃",
                    "胸部": "💗",
                    "小穴": "🌸",
                    "屁眼": "🍑",
                    "大腿": "🦵",
                    "脚部": "👣"
                };

                for (let [key, value] of Object.entries(charData["身体状态"])) {
                    if (value && value[0]) {
                        const emoji = bodyEmojis[key] || "✨";
                        bodyDiv.innerHTML += `<div class="description-item">${emoji} ${key}: ${value[0]}</div>`;
                    }
                }
            }

            // 关系值 - 完全修正的逻辑
            if (charData["关系值"]) {
                const relationsDiv = document.getElementById(`${charId}-relations`);
                relationsDiv.innerHTML = '';

                for (let [key, value] of Object.entries(charData["关系值"])) {
                    if (value === undefined || value === null) continue;

                    let progressClass = '';
                    let emoji = '';
                    let displayValue = Array.isArray(value) ? value[0] : value;
                    let percentage = 0;

                    if (key.includes("好感度")) {
                        progressClass = 'progress-affection';
                        emoji = '💕';
                        // 好感度：负数和0显示0%，正数直接作为百分比
                        percentage = displayValue <= 0 ? 0 : Math.min(displayValue, 100);
                    } else if (key.includes("堕落值")) {
                        progressClass = 'progress-corruption';
                        emoji = '🔥';
                        // 堕落值：负数和0显示0%，正数直接作为百分比
                        percentage = displayValue <= 0 ? 0 : Math.min(displayValue, 100);
                    } else if (key.includes("嫉妒值")) {
                        progressClass = 'progress-jealousy';
                        emoji = '😤';
                        // 嫉妒值：0-100直接显示
                        percentage = Math.max(0, Math.min(displayValue, 100));
                    }

                    // 显示格式
                    let rangeDisplay = key.includes("嫉妒值")
                        ? `${displayValue}/100`
                        : `${displayValue} (-100~100)`;

                    relationsDiv.innerHTML += `
                        <div class="progress-container">
                            <div class="progress-label">
                                <span>${emoji} ${key}</span>
                                <span>${rangeDisplay}</span>
                            </div>
                            <div class="progress-bar">
                                <div class="progress-fill ${progressClass}" style="width: ${percentage}%">
                                    ${percentage}%
                                </div>
                            </div>
                        </div>
                    `;
                }
            }
        }

        function updateUserData(userData) {
            // 基础属性
            if (userData["基础属性"]) {
                const basicAttrs = userData["基础属性"];
                if (basicAttrs["冒险等级"]) {
                    document.getElementById('user-level').textContent = basicAttrs["冒险等级"][0];
                }
                if (basicAttrs["冒险功绩点"] !== undefined) {
                    document.getElementById('user-points').textContent = basicAttrs["冒险功绩点"][0] + " 点";
                }
                if (basicAttrs["职业等级"]) {
                    document.getElementById('user-class').textContent = basicAttrs["职业等级"][0];
                }
            }

            // 外观描述
            if (userData["外观描述"]) {
                const appearanceDiv = document.getElementById('user-appearance');
                appearanceDiv.innerHTML = '';
                const appearanceEmojis = {
                    "头饰": "🎩",
                    "上身": "🛡️",
                    "下身": "👖"
                };

                for (let [key, value] of Object.entries(userData["外观描述"])) {
                    if (value && value[0]) {
                        const emoji = appearanceEmojis[key] || "✨";
                        appearanceDiv.innerHTML += `<div class="description-item">${emoji} ${key}: ${value[0]}</div>`;
                    }
                }
            }

            // 身体状态
            if (userData["身体状态"]) {
                const bodyDiv = document.getElementById('user-body');
                bodyDiv.innerHTML = '';
                const bodyEmojis = {
                    "表情": "😤",
                    "动作": "⚔️",
                    "阴茎": "🍆"
                };

                for (let [key, value] of Object.entries(userData["身体状态"])) {
                    if (value && value[0]) {
                        const emoji = bodyEmojis[key] || "✨";
                        bodyDiv.innerHTML += `<div class="description-item">${emoji} ${key}: ${value[0]}</div>`;
                    }
                }
            }
        }

        // 自动刷新功能（每5秒刷新一次）
        function startAutoRefresh() {
            setInterval(() => {
                loadStatusData();
            }, 5000);
        }

        // 页面加载时执行
        window.onload = function() {
            restoreCollapseStates(); // 恢复折叠状态
            loadStatusData();
            startAutoRefresh(); // 启动自动刷新
        };

        // 监听MVU更新事件（如果存在）
        if (window.addEventListener) {
            window.addEventListener('mvu_updated', function() {
                loadStatusData();
            });
        }
    </script>
